package app.sentier.domain

import java.util.Base64

/**
 * Terres émergées de l'Europe en grille de 0,2 degré, pour les cartes des voyages par pays.
 * Calculée à partir des contours de Natural Earth (domaine public), de 72° N à 34° N et de 25° O à 45° E.
 */
object EuropeMask {
    const val STEP = 0.2
    const val LAT_TOP = 72.0
    const val LAT_BOTTOM = 34.0
    const val LON_LEFT = -25.0
    const val LON_RIGHT = 45.0
    const val COLS = 350
    const val ROWS = 190

    private const val DATA = ""

    private val bits: ByteArray by lazy { Base64.getDecoder().decode(DATA) }

    /** Vrai si la case [col], [row] (0 en haut à gauche, à 25° O et 72° N) est sur la terre ferme. */
    fun isLand(col: Int, row: Int): Boolean {
        if (col !in 0 until COLS || row !in 0 until ROWS) return false
        val i = row * COLS + col
        return (bits[i / 8].toInt() shr (7 - i % 8)) and 1 == 1
    }

    /** Vrai si le point est sur la terre ferme (faux hors de la grille). */
    fun isLandAt(lat: Double, lon: Double): Boolean =
        isLand(Math.floor((lon - LON_LEFT) / STEP).toInt(), Math.floor((LAT_TOP - lat) / STEP).toInt())

    /** Vrai si le cadre [area] est entièrement couvert par la grille. */
    fun covers(area: MapArea): Boolean =
        area.latTop <= LAT_TOP && area.latBottom >= LAT_BOTTOM && area.lonLeft >= LON_LEFT && area.lonRight <= LON_RIGHT
}
